//! Raw bindings to the arcus-memcached headers, generated by `build.rs`.

// Generated code: which of these fire depends on the headers, so `expect` would turn a header
// update into an "unfulfilled expectation" warning.
#![allow(
    dead_code,
    non_camel_case_types,
    non_snake_case,
    non_upper_case_globals,
    unused_qualifications,
    clippy::all,
    clippy::nursery,
    clippy::pedantic,
    clippy::restriction,
    reason = "bindgen output: it keeps the C names, emits every declaration whether used or \
              not, and carries its own `#[allow]`s"
)]

include!(concat!(env!("OUT_DIR"), "/engine_api.rs"));
